def make_palindrome(string: str) -> str:
    """ Find the shortest palindrome that begins with a supplied string. """
    if not string:
        return ""

    # We need to find the longest suffix of 'string' that is a palindrome.
    # Once found, we take the prefix before this suffix, reverse it, 
    # and append it to the end of the original string.
    for i in range(len(string)):
        suffix = string[i:]
        if suffix == suffix[::-1]:
            prefix_to_reverse = string[:i]
            return string + prefix_to_reverse[::-1]

    return string + string[:-1][::-1] # Fallback (logic should hit i=0 if no other)
